    {
      "rank": 1,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations supplied an exceptionally clear, universal framework for irreversibility far from equilibrium, joining fundamental statistical mechanics to directly testable small-system physics.",
        "attribution": "Evans established the pioneering fluctuation-theorem line, Jarzynski supplied the decisive equilibrium-free-energy relation, and Seifert developed the modern stochastic-thermodynamic formulation.",
        "maturity": "The ideas have endured for decades, have extensive theoretical and experimental support, and now organize a broad field.",
        "uncertainties": [
          "Gavin E. Crooks made a major independent contribution, so a three-person award would leave a real attribution tension."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological quantum phases revealed a deep physical structure with consequences across quantum matter, optics, and precision experiments.",
        "attribution": "Aharonov's effect made the physical significance of potentials unmistakable, while Berry identified the general adiabatic geometric phase; the pairing captures two complementary foundations.",
        "maturity": "Both effects are old, repeatedly verified, and central to modern physics.",
        "uncertainties": [
          "The distinct conceptual origins and extensive experimental history make the exact citation boundary unusually broad."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "The defect-mediated theory of two-dimensional melting is a beautiful example of universal statistical physics, explaining how topology and fluctuations reshape phase transitions.",
        "attribution": "Halperin and Nelson provided the central defect-based theory, with Young making the essential related theoretical contribution.",
        "maturity": "Its predictions have informed a large experimental and numerical literature over many decades.",
        "uncertainties": [
          "Real two-dimensional materials and colloidal systems can exhibit nonideal or weakly first-order behavior, complicating a simple universal experimental narrative."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave strongly correlated-electron physics a controlled and extraordinarily productive nonperturbative framework.",
        "attribution": "Vollhardt and collaborators established the infinite-dimensional mean-field construction, while Georges and Kotliar made the method broadly usable and physically transformative.",
        "maturity": "The approach is deeply embedded in correlated-materials theory and has been tested against a wide range of phenomena.",
        "uncertainties": [
          "The intellectual genealogy is distributed across several foundational papers and collaborators, making a three-name attribution difficult."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B020",
      "proposed_laureates": [
        "John Toner",
        "Tamás Vicsek",
        "Yuhai Tu"
      ],
      "assessment": {
        "nobel_worthiness": "Collective motion and the hydrodynamic theory of flocking uncovered an unexpected ordered state in active matter and changed how nonequilibrium collective behavior is understood.",
        "attribution": "Vicsek supplied the influential minimal-model and experimental-style demonstration, while Toner and Tu developed the hydrodynamic theory explaining long-range order.",
        "maturity": "The framework has stimulated extensive work across active matter, biological physics, and statistical mechanics.",
        "uncertainties": [
          "The connection from idealized flocking models to quantitative biological systems remains less settled than the theory's conceptual impact."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps transferred the powerful band-structure idea to light and created a durable foundation for controlling electromagnetic propagation.",
        "attribution": "John and Yablonovitch articulated the central photonic-gap concepts, while Joannopoulos provided foundational theoretical development of photonic-crystal physics.",
        "maturity": "The field has produced a vast experimental and technological literature over several decades.",
        "uncertainties": [
          "Applications have been diverse rather than concentrated in one singular experimental realization."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance converted spin-dependent tunnelling into a robust physical effect with major scientific and technological consequences.",
        "attribution": "Moodera and Miyazaki made key experimental demonstrations, and Parkin was central to establishing high-performance magnetic tunnel junctions and their impact.",
        "maturity": "The effect is well understood, reproducible, and foundational for magnetic-device physics.",
        "uncertainties": [
          "The development involved substantial industrial and materials-science contributions beyond any three individuals."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions furnished an exceptionally clean platform in which quantum information concepts became controllable many-body experiments and computation.",
        "attribution": "Cirac and Zoller supplied decisive theoretical blueprints, while Blatt led landmark experimental realizations.",
        "maturity": "The platform is highly mature, with long-lived experimental validation and continuing fundamental importance.",
        "uncertainties": [
          "Quantum computing has multiple comparably important hardware and theoretical lineages, so isolating trapped ions as the prize-defining contribution is challenging."
        ]
      }
    }
  ]
